INSERT INTO system (id, tenant_id, name, business_owner, technical_owner, origin, vendor_id, hosting, locations, sensitivity, status) VALUES ('a96f20ec-c668-593c-a9f2-6127b78c41fe', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', 'Brightpath resume screener', 'Olivia Grant, Head of Talent Acquisition', 'Terry Lin, Director of IT', 'vendor', 'e9b1f711-f25f-5b15-a7c3-399b745a2bd0', 'Vendor cloud (US), connected to the applicant tracking system', '["US"]'::jsonb, 'moderate', 'testing');
INSERT INTO ai_component (id, tenant_id, name, origin, kind, vendor_id, version, intended_use, inputs, output, trained_on_personal_data, known_limitations) VALUES ('40054717-2ad6-5a05-b200-94002ff234ad', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', 'Brightpath Match Score', 'vendor', 'traditional_model', 'e9b1f711-f25f-5b15-a7c3-399b745a2bd0', '4.2', 'Scores how well an applicant''s resume and application answers match a job''s stated requirements, so recruiters can decide whom to call first.', 'Resume text, application answers (availability, shift preference, licenses such as a commercial driver''s license) and the job''s stated requirements.', 'A match score from 0 to 100 and a rank among applicants for the same job.', true, 'Vendor documentation says the model was trained mostly on US warehouse and logistics hiring data from 2019 to 2024, scores resumes in unusual formats less accurately, and gives lower scores to resumes with employment gaps longer than six months.');
