INSERT INTO processing_activity (id, tenant_id, name, purpose, legal_basis, decision_domain, ai_role, human_review, human_review_note, people_affected, collection, consumer_interaction, disclosures, go_live, stage) VALUES ('5e3c3646-6b72-5223-a53a-ec5f1b4a42f5', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', 'AI resume screening for warehouse and driver roles', 'Rank applicants for warehouse and driver roles by how well they meet each job''s stated requirements, so recruiters call the strongest matches first and fill open shifts faster.', NULL, 'employment', 'materially_influences', 'limited', 'Recruiters see each applicant''s score and rank and can call anyone, but in practice they work down the ranked list and do not review resumes ranked below the top 25.', '{"job_applicants": {"US-CA": 21000, "US-CO": 6500, "US-NYC": 4200, "US-other": 16300}}'::jsonb, 'Applicants apply on Harbor''s careers site. The applicant tracking system stores the application and sends the resume and answers to the screener, which returns a score and rank to the applicant tracking system.', 'Applicants apply online for a specific job; Harbor contacts them by phone or email to schedule a screening call.', 'Harbor''s applicant privacy notice, linked from every job posting, says applications may be reviewed with automated tools. No separate notice about the screener exists yet.', '2027-01-15', 'testing');
