INSERT INTO activity_recipient (tenant_id, activity_id, vendor_id, purpose) VALUES ('ff3e39f3-ea89-5b8d-9af6-2638c94349e3', '5e3c3646-6b72-5223-a53a-ec5f1b4a42f5', 'b35adbec-333a-51ae-a35c-08b7c01e4853', 'Hosts and stores applications and screening results.');
INSERT INTO policy (id, tenant_id, template_id, title) VALUES ('6152be94-0673-5b08-b189-45c7ceb5abb7', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', 'ai-governance', 'AI governance and acceptable AI use');
INSERT INTO policy_version (id, tenant_id, policy_id, version, template_version, sections, status, proposed_by, confirmed_by, confirmed_at, effective_from) VALUES ('fff9c6c8-4487-5559-83fd-0d49627d253d', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', '6152be94-0673-5b08-b189-45c7ceb5abb7', 1, '0.1.0', '[{"number": "1", "text": "This policy sets the rules for choosing, building and using AI systems at Harbor Staffing. It makes sure AI helps people do their jobs without harming the people it is used on, and that a named person is always responsible for each system.", "title": "Purpose"}, {"number": "2", "text": "This policy covers every AI system Harbor Staffing builds, buys or uses, including AI features inside other software. It applies to all employees and contractors, and to vendors who run AI systems for us.", "title": "Scope"}, {"number": "3", "text": "- **System owner:** the business leader responsible for an AI system and how it is used.\n- **Privacy office:** the privacy analysts, privacy counsel and data protection officer\n  (DPO) who assess AI systems and approve them for use.\n- **DPO:** approves high-risk AI uses and any exception to this policy.", "title": "Roles"}, {"number": "4", "text": "4.1 Every AI system is recorded in the inventory, with a named system owner, before it is used.\n\n4.2 The system owner submits an intake for every new AI system or new use of an existing one.\nThe privacy office decides whether a risk assessment is needed, following the Privacy and AI\nrisk assessment policy.\n\n4.3 An AI system that is used in hiring or promotion decisions is tested for unequal results\nacross groups of people before first use. See section 6.", "title": "Before an AI system is used"}, {"number": "5", "text": "5.1 When an AI system plays a real part in a decision about someone''s job, credit, housing,\neducation or healthcare, a person must review the outcome before it takes effect. That person\nmust understand what the system''s output means, look at other relevant information, and have\nthe authority to change the outcome.\n\n5.2 People are told, in plain language and before the AI system is used, that it will be used\nin a decision about them, and how to ask for a person to review the decision.\n\n5.3 We do not use AI to detect people''s emotions, or to guess their race, health, religion,\nsexual orientation or other protected characteristics, in decisions about them.", "title": "Decisions about people"}, {"number": "6", "text": "6.1 Hiring and promotion tools are tested for unequal results by sex and by race and ethnicity\nbefore first use and at least once a year after that. Someone independent of the team that\nuses the tool does the testing.\n\n6.2 If, for any group, the selection rate divided by the rate of the most-selected group falls\nbelow 0.80, the privacy counsel and the DPO review the tool before it is used again.", "title": "Testing for unfair results"}, {"number": "7", "text": "7.1 A vendor may use our personal information to train or improve its AI models only if our\ncontract with the vendor allows it and the DPO approves it in writing.\n\n7.2 Contracts with AI vendors require the vendor to tell us about changes to the model that\ncould change its results, such as retraining or a new version.", "title": "Vendors"}, {"number": "8", "text": "8.1 Staff may use only the AI tools on the approved list for work.\n\n8.2 Staff must not enter personal information about applicants, employees or customers into\nan AI tool that is not on the approved list.", "title": "Acceptable use of AI tools by staff"}, {"number": "9", "text": "Exceptions to this policy need the DPO''s written approval, with a reason and an end date. The DPO reviews this policy at least once a year.", "title": "Exceptions and review"}]'::jsonb, 'confirmed', '03ab32ab-8a26-502f-8442-0e312d8a4810', 'c1dcb056-f864-5447-8963-5225af8c4aff', '2026-10-15T15:00:00Z', '2026-10-15');
INSERT INTO policy_position (id, tenant_id, policy_version_id, position_key, section, type, statement, applies_to, parameters, framework_refs) VALUES ('d7149c4b-e30d-5b96-9bc0-2eec6856d5be', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', 'fff9c6c8-4487-5559-83fd-0d49627d253d', 'POS-AI-001', '4.1', 'requirement', 'Every AI system is recorded in the inventory, with a named system owner, before it is used.', '{}'::jsonb, '{"inventory_before_use": true}'::jsonb, '["NIST AI RMF GOVERN"]'::jsonb);
INSERT INTO policy_position (id, tenant_id, policy_version_id, position_key, section, type, statement, applies_to, parameters, framework_refs) VALUES ('4238f442-ea45-52ba-baa7-0466cfdd4a0c', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', 'fff9c6c8-4487-5559-83fd-0d49627d253d', 'POS-AI-002', '5.1', 'requirement', 'When an AI system plays a real part in a decision about someone''s job, credit, housing, education or healthcare, a person who understands the output, looks at other relevant information and can change the outcome reviews it before it takes effect.', '{"decision_domains": ["employment", "lending", "housing", "education", "healthcare"]}'::jsonb, '{"human_review": "meaningful", "when": "before_outcome_takes_effect"}'::jsonb, '["NIST AI RMF GOVERN", "NIST AI RMF MANAGE"]'::jsonb);
INSERT INTO policy_position (id, tenant_id, policy_version_id, position_key, section, type, statement, applies_to, parameters, framework_refs) VALUES ('ffd23b25-39fc-561a-a82b-24dc36681502', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', 'fff9c6c8-4487-5559-83fd-0d49627d253d', 'POS-AI-003', '5.2', 'requirement', 'People are told in plain language, before the AI system is used, that it will be used in a decision about them and how to ask for a person to review it.', '{"decision_domains": ["employment", "lending", "housing", "education", "healthcare"]}'::jsonb, '{"includes_human_review_route": true, "notice": "before_use"}'::jsonb, '["NIST AI RMF GOVERN", "NIST Privacy Framework CM.AW-P"]'::jsonb);
INSERT INTO policy_position (id, tenant_id, policy_version_id, position_key, section, type, statement, applies_to, parameters, framework_refs) VALUES ('583b339c-141f-5443-a124-956ca4de59cb', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', 'fff9c6c8-4487-5559-83fd-0d49627d253d', 'POS-AI-004', '5.3', 'prohibition', 'AI is not used to detect people''s emotions, or to guess their protected characteristics, in decisions about them.', '{}'::jsonb, '{"emotion_recognition": false, "infer_protected_characteristics": false}'::jsonb, '["NIST AI RMF MAP"]'::jsonb);
INSERT INTO policy_position (id, tenant_id, policy_version_id, position_key, section, type, statement, applies_to, parameters, framework_refs) VALUES ('ad885d0a-c4c7-50f1-8b1b-da3c9edd3bfd', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', 'fff9c6c8-4487-5559-83fd-0d49627d253d', 'POS-AI-005', '6.1', 'requirement', 'Hiring and promotion tools are tested by someone independent for unequal results by sex and by race and ethnicity, before first use and at least once a year.', '{"decision_domains": ["employment"]}'::jsonb, '{"bias_testing": ["before_first_use", "annually"], "groups": ["sex", "race_ethnicity"], "independent_tester": true}'::jsonb, '["NIST AI RMF MEASURE"]'::jsonb);
INSERT INTO policy_position (id, tenant_id, policy_version_id, position_key, section, type, statement, applies_to, parameters, framework_refs) VALUES ('439f4013-0f26-55ed-b3d9-5fb3138ef2f6', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', 'fff9c6c8-4487-5559-83fd-0d49627d253d', 'POS-AI-006', '6.2', 'threshold', 'If any group''s selection rate divided by the most-selected group''s rate falls below 0.80, privacy counsel and the DPO review the tool before it is used again.', '{"decision_domains": ["employment"]}'::jsonb, '{"impact_ratio_floor": 0.8, "review_by": ["privacy_counsel", "dpo"]}'::jsonb, '["NIST AI RMF MEASURE", "NIST AI RMF MANAGE"]'::jsonb);
INSERT INTO policy_position (id, tenant_id, policy_version_id, position_key, section, type, statement, applies_to, parameters, framework_refs) VALUES ('29ad2140-a2d1-59cc-9001-23afa087e24a', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', 'fff9c6c8-4487-5559-83fd-0d49627d253d', 'POS-AI-007', '7.1', 'conditional_permission', 'A vendor may train or improve its AI models on our personal information only if the contract allows it and the DPO approves it in writing.', '{}'::jsonb, '{"vendor_training_on_our_data": {"requires": ["contract_allows", "dpo_written_approval"]}}'::jsonb, '["NIST CSF 2.0 GV.SC"]'::jsonb);
INSERT INTO policy_position (id, tenant_id, policy_version_id, position_key, section, type, statement, applies_to, parameters, framework_refs) VALUES ('f47eab40-9ed0-503f-8186-d8fb44e8ea3c', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', 'fff9c6c8-4487-5559-83fd-0d49627d253d', 'POS-AI-008', '8.2', 'prohibition', 'Staff do not enter personal information about applicants, employees or customers into an AI tool that is not on the approved list.', '{}'::jsonb, '{"unapproved_tools_personal_information": false}'::jsonb, '["NIST CSF 2.0 PR.AT"]'::jsonb);
INSERT INTO policy (id, tenant_id, template_id, title) VALUES ('deced142-2676-5189-b9a2-dd056ad5dc1f', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', 'risk-assessment', 'Privacy and AI risk assessment');
INSERT INTO policy_version (id, tenant_id, policy_id, version, template_version, sections, status, proposed_by, confirmed_by, confirmed_at, effective_from) VALUES ('54fe1e40-d121-5d6f-a991-6fcac7f01717', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', 'deced142-2676-5189-b9a2-dd056ad5dc1f', 1, '0.1.0', '[{"number": "1", "text": "This policy sets out when Harbor Staffing assesses the privacy and AI risks of a new activity, how the risks are rated, and who approves the assessment.", "title": "Purpose"}, {"number": "2", "text": "2.1 A risk assessment is done before any activity that the intake triage says needs one,\nand before the activity starts.\n\n2.2 An activity that is already running when the need is found is assessed as a priority.", "title": "When an assessment is needed"}, {"number": "3", "text": "3.1 Each risk is rated for how likely it is and how bad it would be, on five levels from very\nlow to very high. The two ratings combine into a risk level using the organization''s risk\nmatrix (OpenDPO default method, version 1.0.0, based on NIST SP 800-30).\n\n3.2 Each risk is rated twice: before safeguards and after them.\n\n3.3 An AI draft of an assessment is only a draft. A named person reviews and edits it, and\npeople make every approval.", "title": "How risks are rated"}, {"number": "4", "text": "4.1 Approval depends on the highest risk before safeguards:\n\n- **Low:** a privacy analyst who did not draft or submit the assessment.\n- **Medium:** a privacy analyst gives a provisional approval, then privacy counsel approves.\n- **High:** a privacy analyst gives a provisional approval, then the DPO and privacy counsel\n  both approve. They must be two different people.\n\n4.2 Some activities are high risk whatever the scores: using automated decision technology to\nmake a significant decision about someone under the CCPA Regulations, and using covered\nautomated decision technology in a consequential decision under Colorado law.\n\n4.3 No one approves an assessment they submitted, drafted or substantially edited.", "title": "Who approves"}, {"number": "5", "text": "If a risk is still high or very high after safeguards, the activity does not go ahead unless the DPO records a risk acceptance: the DPO''s name, the reason, the risk accepted and a date to review it.", "title": "Accepting remaining risk"}, {"number": "6", "text": "6.1 Assessments are reviewed at least once a year for high and very high risk, every two years\nfor moderate risk and every three years for low risk.\n\n6.2 A material change, such as retraining a model, changing vendor, an incident, or a change\nin the law, means the assessment is updated within 45 calendar days.", "title": "Keeping assessments current"}]'::jsonb, 'confirmed', '03ab32ab-8a26-502f-8442-0e312d8a4810', 'c1dcb056-f864-5447-8963-5225af8c4aff', '2026-10-15T15:00:00Z', '2026-10-15');
INSERT INTO policy_position (id, tenant_id, policy_version_id, position_key, section, type, statement, applies_to, parameters, framework_refs) VALUES ('34db0a85-6a0f-5e1a-b880-75aaf8a7624e', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', '54fe1e40-d121-5d6f-a991-6fcac7f01717', 'POS-RA-001', '2.1', 'requirement', 'A risk assessment is done before any activity that triage says needs one, and before the activity starts.', '{}'::jsonb, '{"timing": "before_start"}'::jsonb, '["NIST Privacy Framework ID.RA-P"]'::jsonb);
INSERT INTO policy_position (id, tenant_id, policy_version_id, position_key, section, type, statement, applies_to, parameters, framework_refs) VALUES ('c14adb04-deeb-5137-970f-cc5ffc9c5d0a', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', '54fe1e40-d121-5d6f-a991-6fcac7f01717', 'POS-RA-002', '3.1', 'default', 'Risks are rated on the OpenDPO default five-level method, version 1.0.0.', '{}'::jsonb, '{"methodology": "opendpo-default-5x5", "methodology_version": "1.0.0"}'::jsonb, '["NIST AI RMF MEASURE"]'::jsonb);
INSERT INTO policy_position (id, tenant_id, policy_version_id, position_key, section, type, statement, applies_to, parameters, framework_refs) VALUES ('a14b7635-8b3c-5d1f-a608-27bb13528b12', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', '54fe1e40-d121-5d6f-a991-6fcac7f01717', 'POS-RA-003', '3.3', 'requirement', 'An AI draft is only a draft; a named person reviews it and people make every approval.', '{}'::jsonb, '{"ai_may_approve": false}'::jsonb, '["NIST AI RMF GOVERN"]'::jsonb);
INSERT INTO policy_position (id, tenant_id, policy_version_id, position_key, section, type, statement, applies_to, parameters, framework_refs) VALUES ('3a2ece6e-5bc7-56a8-8151-1c4836155dbd', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', '54fe1e40-d121-5d6f-a991-6fcac7f01717', 'POS-RA-004', '4.1', 'approval_rule', 'Low risk: one analyst who did not draft it. Medium: analyst provisional approval, then privacy counsel. High: analyst provisional approval, then the DPO and privacy counsel, two different people.', '{}'::jsonb, '{"routing": {"high": {"distinct_people": true, "final": ["dpo", "privacy_counsel"], "provisional": ["privacy_analyst"]}, "low": {"final": ["privacy_analyst"], "provisional": []}, "medium": {"final": ["privacy_counsel"], "provisional": ["privacy_analyst"]}}}'::jsonb, '["NIST Privacy Framework GV.PO-P"]'::jsonb);
INSERT INTO policy_position (id, tenant_id, policy_version_id, position_key, section, type, statement, applies_to, parameters, framework_refs) VALUES ('49f32d54-57e5-5d67-83cc-8a8e0408ac8b', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', '54fe1e40-d121-5d6f-a991-6fcac7f01717', 'POS-RA-005', '4.2', 'approval_rule', 'Automated decision technology used for a significant decision (CCPA Regulations) or covered automated decision technology in a consequential decision (Colorado) is high risk whatever the scores.', '{}'::jsonb, '{"high_floor_rules": ["CCPA-RA-ADMT", "CO-CLASS-COVERED-ADMT"]}'::jsonb, '["NIST AI RMF MAP"]'::jsonb);
INSERT INTO policy_position (id, tenant_id, policy_version_id, position_key, section, type, statement, applies_to, parameters, framework_refs) VALUES ('9b63b733-b903-5f4b-8535-7068b9394ffe', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', '54fe1e40-d121-5d6f-a991-6fcac7f01717', 'POS-RA-006', '4.3', 'prohibition', 'No one approves an assessment they submitted, drafted or substantially edited.', '{}'::jsonb, '{"self_approval": false}'::jsonb, '["NIST Privacy Framework GV.PO-P"]'::jsonb);
INSERT INTO policy_position (id, tenant_id, policy_version_id, position_key, section, type, statement, applies_to, parameters, framework_refs) VALUES ('4a835709-4a4d-5a10-9340-b469522d97d3', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', '54fe1e40-d121-5d6f-a991-6fcac7f01717', 'POS-RA-007', '5', 'threshold', 'A risk still high or very high after safeguards blocks going ahead unless the DPO records a risk acceptance with a reason and a review date.', '{}'::jsonb, '{"acceptance_by": "dpo", "acceptance_needed_at": "high", "records": ["name", "reason", "risk", "review_date"]}'::jsonb, '["NIST AI RMF MANAGE"]'::jsonb);
INSERT INTO policy_position (id, tenant_id, policy_version_id, position_key, section, type, statement, applies_to, parameters, framework_refs) VALUES ('49bf1c13-525d-5ffc-9e4f-86ef66bd69d8', 'ff3e39f3-ea89-5b8d-9af6-2638c94349e3', '54fe1e40-d121-5d6f-a991-6fcac7f01717', 'POS-RA-008', '6', 'requirement', 'Review every year for high and very high risk, every two years for moderate and every three years for low; update within 45 calendar days of a material change.', '{}'::jsonb, '{"material_change_days": 45, "review_years": {"high": 1, "low": 3, "moderate": 2, "very_high": 1, "very_low": 3}}'::jsonb, '["NIST Privacy Framework ID.RA-P"]'::jsonb);
